package com.example.statusdrafter.config; import com.example.statusdrafter.entity.User; import com.example.statusdrafter.repository.UserRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner init(UserRepository repo,PasswordEncoder encoder,@Value("${app.admin.username}")String u,@Value("${app.admin.password}")String p,@Value("${app.admin.name}")String n,@Value("${app.admin.email}")String e){return args->{if(repo.findByUsername(u).isEmpty())repo.save(new User(n,u,e,encoder.encode(p),User.Role.ADMIN));};}}
